from functools import lru_cache

@lru_cache(maxsize=None)
def climb_stairs_memo(n):
    # Top-down: how many ways to climb n stairs?
    if n <= 2:
        return n
    return climb_stairs_memo(n - 1) + climb_stairs_memo(n - 2)

def climb_stairs_dp(n):
    # Bottom-up: use a DP table
    if n <= 2:
        return n
    dp = [0] * (n + 1)
    dp[1], dp[2] = 1, 2
    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

for i in range(1, 8):
    print(f'n={i}: memo={climb_stairs_memo(i)}, dp={climb_stairs_dp(i)}')
